sys_script.script:
(function executeRule(current, previous) {
    // STRY0019513 04/02/26 - Enforce state transition restrictions

    // 1. Admin Override: If the user has the admin role, bypass these restrictions
    if (gs.hasRole('admin')) {
        return;
    }

    // 2. Optimization: Exit early if state hasn't changed or if it's a new record
    if (current.isNewRecord() || !current.state.changes()) {
        return;
    }

    var prevState = previous.getValue('state');
    var newState = current.getValue('state');

    // 3. Restriction: From Complete (400) -> Must be Reopened (8)
    if (prevState == '400' && newState !== '8') {
        gs.addErrorMessage('Completed cases can only be moved to a Reopened state.');
        current.setAbortAction(true);
    }

    // 4. Restriction: From Reopened (8) -> Must be Complete (400) or Cancelled (7)
    else if (prevState == '8' && newState !== '400' && newState !== '7') {
        gs.addErrorMessage('Reopened cases can only be moved to Complete or Cancelled.');
        current.setAbortAction(true);
    }

})(current, previous);
